const items = $input.all();

for (const item of items) {
  let rawText = item.json.output[0].content[0].text;

  // Remove markdown code block if present
  rawText = rawText.replace(/```json/g, '').replace(/```/g, '').trim();

  try {
    const parsed = JSON.parse(rawText);
    item.json.intent = parsed;
  } catch (error) {
    item.json.intent = { error: "Invalid JSON format", raw: rawText };
  }
}

return items;

const transcript = $input.first().json.body.call.transcript_object;

if (!Array.isArray(transcript)) {
  return [{ json: { conversation: "" } }];
}

// Step 1: Collect user turns with their previous agent message
let pairs = [];

for (let i = 0; i < transcript.length; i++) {
  if (transcript[i].role === "user") {

    let previousAgent = "";

    // Find closest previous agent message
    for (let j = i - 1; j >= 0; j--) {
      if (transcript[j].role === "agent") {
        previousAgent = transcript[j].content?.trim() || "";
        break;
      }
    }

    pairs.push({
      agent: previousAgent,
      user: transcript[i].content?.trim() || ""
    });
  }
}

// Step 2: Take only last 5 conversations
const lastFive = pairs.slice(-5);

// Step 3: Format cleanly
let formatted = lastFive.map((p, index) => {
  return `${index + 1}. Agent: ${p.agent}\nUser: ${p.user}`;
}).join("\n\n");

return [
  {
    json: {
      conversation: formatted
    }
  }
];
